package dinkbingo;

import dinkbingo.BingoResponses.ClaimResponse;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import okhttp3.HttpUrl;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.StringJoiner;

/**
 * Hands a successful claim to Dink, which renders the embed, attaches the screenshot, and
 * performs the actual webhook POST.
 * <p>
 * Announcing client-side rather than from the backend is what makes screenshot proof
 * possible — the backend has no view of the game.
 * <p>
 * Requires the user to enable Dink's <em>External Plugin Requests &gt; Enable External Plugin
 * Notifications</em>. If Dink is absent or that setting is off, the message is silently
 * dropped by Dink; set {@code announce_from_backend} on the sheet as the fallback.
 *
 * @see <a href="https://github.com/pajlads/DinkPlugin/blob/master/docs/external-plugin-messaging.md">Dink external plugin messaging</a>
 */
@Slf4j
@Singleton
public class BingoAnnouncer {

    private static final String DINK_NAMESPACE = "dink";
    private static final String DINK_NOTIFY = "notify";
    private static final String SOURCE_PLUGIN = "Bingo with Dink Notifications";
    private static final String ITEM_ICON_URL = "https://static.runelite.net/cache/item/icon/";
    private static final String WIKI_SEARCH_URL = "https://oldschool.runescape.wiki/w/Special:Search?search=";

    private final EventBus eventBus;
    private final BingoConfig config;

    @Inject
    public BingoAnnouncer(EventBus eventBus, BingoConfig config) {
        this.eventBus = eventBus;
        this.config = config;
    }

    public void announce(ClaimResponse claim, String source) {
        if (claim == null || !claim.isAnnounceable()) {
            return;
        }

        String itemName = claim.getItemName() != null ? claim.getItemName() : "an item";
        String tileName = claim.getTileName() != null ? claim.getTileName() : itemName;
        String team = claim.getTeam() != null ? claim.getTeam() : "their team";
        String text = claim.isProgress() ? config.progressMessage() : config.notifyMessage();
        String title = claim.isProgress() ? "Bingo tile progress" : "Bingo tile completed";
        post(claim, source, itemName, tileName, team, text, title);
    }

    private void post(
        ClaimResponse claim,
        String source,
        String itemName,
        String tileName,
        String team,
        String text,
        String title
    ) {

        Map<String, Object> data = new HashMap<>();
        data.put("sourcePlugin", SOURCE_PLUGIN);
        data.put("text", text);
        data.put("title", title);
        data.put("thumbnail", ITEM_ICON_URL + claim.getItemId() + ".png");
        data.put("imageRequested", config.sendScreenshot());

        Map<String, Object> replacements = new HashMap<>();
        replacements.put("%ITEM%", linkReplacement(itemName, WIKI_SEARCH_URL + urlEncode(itemName)));
        replacements.put("%TILE%", textReplacement(tileName));
        replacements.put("%TEAM%", textReplacement(team));
        replacements.put("%PROGRESS%", textReplacement(String.valueOf(claim.getProgress())));
        replacements.put("%REQUIRED%", textReplacement(String.valueOf(claim.getRequired())));
        replacements.put("%REMAINING%", textReplacement(String.valueOf(claim.getRemaining())));
        replacements.put("%SOURCE%", textReplacement(source != null ? source : "unknown"));
        data.put("replacements", replacements);

        List<Map<String, Object>> fields = new ArrayList<>(6);
        if (!tileName.equalsIgnoreCase(itemName)) {
            fields.add(field("Bingo Tile", tileName, false));
            fields.add(field(claim.isProgress() ? "Contributed Item" : "Completing Item",
                itemName, false));
        }
        fields.add(field("Progress", claim.getProgress() + " / " + claim.getRequired(), true));
        fields.add(field("Team", team, true));
        fields.add(field("Tiles Remaining", claim.getRemaining() + " / " + claim.getTotal(), true));
        if (claim.getClaimedItems() != null && !claim.getClaimedItems().isEmpty()) {
            StringJoiner credited = new StringJoiner(", ");
            for (BingoResponses.BoardClaimedItem contribution : claim.getClaimedItems()) {
                credited.add(contribution.getName());
            }
            fields.add(field("Credited Items", credited.toString(), false));
        }
        if (source != null && !source.isEmpty()) {
            fields.add(field("Source", source, true));
        }
        data.put("fields", fields);

        Map<String, Object> metadata = new HashMap<>();
        metadata.put("itemId", claim.getItemId());
        metadata.put("itemName", itemName);
        metadata.put("tileId", claim.getTileId());
        metadata.put("tileName", tileName);
        metadata.put("team", team);
        metadata.put("remaining", claim.getRemaining());
        metadata.put("points", claim.getPoints());
        metadata.put("progress", claim.getProgress());
        metadata.put("required", claim.getRequired());
        metadata.put("complete", claim.isComplete());
        data.put("metadata", metadata);

        // Dink rejects the whole request unless every element is an okhttp3.HttpUrl.
        String webhook = config.bingoWebhook().trim();
        if (!webhook.isEmpty()) {
            List<HttpUrl> urls = new ArrayList<>();
            for (String candidate : webhook.split("\n")) {
                HttpUrl url = HttpUrl.parse(candidate.trim());
                if (url != null && url.isHttps()) {
                    urls.add(url);
                }
            }
            if (!urls.isEmpty()) {
                data.put("urls", urls);
            }
        }

        log.info("Announcing bingo {} for {}", claim.isProgress() ? "progress" : "completion", itemName);
        eventBus.post(new PluginMessage(DINK_NAMESPACE, DINK_NOTIFY, data));
    }

    // ------------------------------------------------------------------
    // Dink payload helpers (see Dink's docs/external-plugin-messaging.md)
    // ------------------------------------------------------------------

    private static Map<String, Object> field(String name, String value, boolean inline) {
        Map<String, Object> field = new HashMap<>(3);
        field.put("name", name);
        field.put("value", value);
        field.put("inline", inline);
        return field;
    }

    private static Map<String, String> textReplacement(String text) {
        Map<String, String> replacement = new HashMap<>(1);
        replacement.put("value", text);
        return replacement;
    }

    private static Map<String, String> linkReplacement(String text, String link) {
        Map<String, String> replacement = new HashMap<>(2);
        replacement.put("value", text);
        replacement.put("richValue", "[" + text + "](" + link + ")");
        return replacement;
    }

    private static String urlEncode(String text) {
        return text.replace(" ", "+");
    }
}

package dinkbingo;

import lombok.Getter;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * An immutable snapshot of the board for one team.
 * <p>
 * Replaced wholesale on each fetch rather than mutated, so a detection thread reading
 * {@link #getRemaining()} always sees a coherent view.
 */
@Getter
public final class BingoBoard {

    public static final BingoBoard EMPTY = new BingoBoard(null, Collections.emptyList(), false);

    /** The team the local player belongs to, or null if the backend does not recognise the RSN. */
    @Nullable
    private final String team;

    private final List<BingoTile> tiles;

    private final boolean eventOpen;

    private final Map<Integer, BingoTile> byItemId;

    private final Map<String, BingoTile> byTileId;

    /** Logical tile ids this team has not claimed yet. */
    private final Set<String> remaining;

    /** Accepted item ids not yet credited for their logical tile. */
    private final Set<Integer> openItemIds;

    public BingoBoard(@Nullable String team, List<BingoTile> tiles, boolean eventOpen) {
        this.team = team;
        this.tiles = Collections.unmodifiableList(new ArrayList<>(tiles));
        this.eventOpen = eventOpen;

        Map<Integer, BingoTile> byItemId = new LinkedHashMap<>();
        Map<String, BingoTile> byTileId = new LinkedHashMap<>();
        Set<String> remaining = new LinkedHashSet<>();
        Set<Integer> openItemIds = new LinkedHashSet<>();
        for (BingoTile tile : tiles) {
            if (byTileId.put(tile.getId(), tile) != null) {
                throw new IllegalArgumentException("Duplicate tile id: " + tile.getId());
            }
            Set<Integer> credited = new LinkedHashSet<>();
            for (BingoContribution contribution : tile.getClaimedItems()) {
                credited.add(contribution.getId());
            }
            for (BingoItem option : tile.getOptions()) {
                if (byItemId.put(option.getId(), tile) != null) {
                    throw new IllegalArgumentException("Item belongs to multiple tiles: " + option.getId());
                }
                if (!tile.isClaimed() && !credited.contains(option.getId())) {
                    openItemIds.add(option.getId());
                }
            }
            if (!tile.isClaimed()) {
                remaining.add(tile.getId());
            }
        }
        this.byItemId = Collections.unmodifiableMap(byItemId);
        this.byTileId = Collections.unmodifiableMap(byTileId);
        this.remaining = Collections.unmodifiableSet(remaining);
        this.openItemIds = Collections.unmodifiableSet(openItemIds);
    }

    /**
     * Whether a drop of this item should be submitted as a claim.
     * <p>
     * A tile we already know is claimed is deliberately not resubmitted: the backend would
     * reject it anyway, and resubmitting is how the audit log fills with noise.
     */
    public boolean isClaimable(int itemId) {
        BingoTile tile = byItemId.get(itemId);
        return eventOpen && team != null && tile != null && openItemIds.contains(itemId);
    }

    public int getRemainingCount() {
        return remaining.size();
    }

    @Nullable
    public BingoItem findOption(int itemId) {
        BingoTile tile = byItemId.get(itemId);
        if (tile == null) {
            return null;
        }
        for (BingoItem option : tile.getOptions()) {
            if (option.getId() == itemId) {
                return option;
            }
        }
        return null;
    }

    /** Whether the backend recognised our RSN and gave us a team. */
    public boolean isConfigured() {
        return team != null;
    }
}

package dinkbingo;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import dinkbingo.BingoResponses.BoardItem;
import dinkbingo.BingoResponses.BoardClaimedItem;
import dinkbingo.BingoResponses.BoardRequest;
import dinkbingo.BingoResponses.BoardResponse;
import dinkbingo.BingoResponses.BoardTile;
import dinkbingo.BingoResponses.ClaimRequest;
import dinkbingo.BingoResponses.ClaimResponse;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * Talks to the Apps Script backend.
 * <p>
 * Every call runs on the injected executor and never on the client thread. Retries reuse
 * the caller's {@code claimId}, which the backend treats as an idempotency key, so a retry
 * after a timeout can never produce a second claim.
 */
@Slf4j
@Singleton
public class BingoClient {

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final int MAX_ATTEMPTS = 4;
    private static final long BASE_BACKOFF_MS = 1500L;

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final ScheduledExecutorService executor;
    private final BingoConfig config;

    @Inject
    public BingoClient(OkHttpClient httpClient, Gson gson, ScheduledExecutorService executor, BingoConfig config) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.executor = executor;
        this.config = config;
    }

    /** Whether the user has pointed us at a backend. Until then we make no requests at all. */
    public boolean isConfigured() {
        return !config.backendUrl().trim().isEmpty() && parseUrl() != null;
    }

    public CompletableFuture<BingoBoard> fetchBoard(String rsn) {
        HttpUrl base = parseUrl();
        if (base == null || rsn == null) {
            return CompletableFuture.completedFuture(BingoBoard.EMPTY);
        }

        BoardRequest boardRequest = new BoardRequest();
        boardRequest.setAction("board");
        boardRequest.setToken(config.eventToken());
        boardRequest.setRsn(rsn);
        Request request = new Request.Builder()
            .url(base)
            .post(RequestBody.create(JSON, gson.toJson(boardRequest)))
            .build();

        return executeWithRetry(request, BoardResponse.class).thenApply(res -> {
            if (res == null || res.getTiles() == null) {
                log.debug("Board fetch returned nothing usable");
                return null;
            }
            if (res.getError() != null) {
                log.warn("Bingo backend rejected board fetch: {}", res.getError());
                return null;
            }
            List<BingoTile> tiles = new ArrayList<>(res.getTiles().size());
            for (BoardTile tile : res.getTiles()) {
                List<BingoItem> options = new ArrayList<>();
                if (tile.getOptions() != null) {
                    for (BoardItem option : tile.getOptions()) {
                        options.add(new BingoItem(option.getId(), option.getName()));
                    }
                }
                BoardItem won = tile.getClaimedItem();
                BingoItem claimedItem = won == null ? null : new BingoItem(won.getId(), won.getName());
                List<BingoContribution> claimedItems = new ArrayList<>();
                if (tile.getClaimedItems() != null) {
                    for (BoardClaimedItem credited : tile.getClaimedItems()) {
                        claimedItems.add(new BingoContribution(
                            credited.getId(),
                            credited.getName(),
                            credited.getClaimedBy(),
                            credited.getClaimedAt()
                        ));
                    }
                }
                tiles.add(new BingoTile(
                    tile.getId(), tile.getName(), tile.getPoints(), tile.getRequired(),
                    tile.getProgress(), options, claimedItems, tile.isClaimed(),
                    tile.getClaimedBy(), tile.getClaimedAt(), claimedItem
                ));
            }
            return new BingoBoard(res.getTeam(), tiles, res.isEventOpen());
        });
    }

    public CompletableFuture<ClaimResponse> submitClaim(ClaimRequest claim) {
        HttpUrl url = parseUrl();
        if (url == null) {
            return CompletableFuture.completedFuture(null);
        }

        claim.setToken(config.eventToken());
        Request request = new Request.Builder()
            .url(url)
            .post(RequestBody.create(JSON, gson.toJson(claim)))
            .build();

        return executeWithRetry(request, ClaimResponse.class);
    }

    // ------------------------------------------------------------------
    // internals
    // ------------------------------------------------------------------

    private HttpUrl parseUrl() {
        HttpUrl url = HttpUrl.parse(config.backendUrl().trim());
        if (url == null) {
            return null;
        }
        if (url.isHttps() || isLoopback(url.host())) {
            return url;
        }
        log.warn("Bingo backend URL must use HTTPS");
        return null;
    }

    private static boolean isLoopback(String host) {
        return "localhost".equalsIgnoreCase(host)
            || "127.0.0.1".equals(host)
            || "::1".equals(host);
    }

    private <T> CompletableFuture<T> executeWithRetry(Request request, Class<T> type) {
        CompletableFuture<T> future = new CompletableFuture<>();
        attempt(request, type, 1, future);
        return future;
    }

    private <T> void attempt(Request request, Class<T> type, int attemptNumber, CompletableFuture<T> future) {
        executor.execute(() -> {
            if (future.isDone()) {
                return;
            }
            try (Response response = httpClient.newCall(request).execute()) {
                if (response.isSuccessful()) {
                    ResponseBody body = response.body();
                    String raw = body != null ? body.string() : "";
                    try {
                        T parsed = gson.fromJson(raw, type);
                        if (isRetryable(parsed) && attemptNumber < MAX_ATTEMPTS) {
                            retry(request, type, attemptNumber, future, "retryable backend response");
                        } else {
                            future.complete(parsed);
                        }
                    } catch (JsonSyntaxException e) {
                        // Apps Script serves an HTML error page when the deployment is
                        // misconfigured. Never log the response body because a custom backend
                        // could reflect request credentials into it.
                        log.warn("Bingo backend returned non-JSON (check the deployment is " +
                            "'Execute as: Me' and 'Who has access: Anyone')");
                        future.complete(null);
                    }
                    return;
                }

                if (isRetryableHttp(response.code()) && attemptNumber < MAX_ATTEMPTS) {
                    retry(request, type, attemptNumber, future, "HTTP " + response.code());
                } else {
                    log.warn("Bingo backend returned HTTP {}", response.code());
                    future.complete(null);
                }
            } catch (IOException e) {
                if (attemptNumber < MAX_ATTEMPTS) {
                    retry(request, type, attemptNumber, future, e.toString());
                } else {
                    log.warn("Bingo backend unreachable after {} attempts", MAX_ATTEMPTS, e);
                    future.complete(null);
                }
            } catch (Exception e) {
                log.warn("Unexpected failure talking to the bingo backend", e);
                future.complete(null);
            }
        });
    }

    private static boolean isRetryable(Object response) {
        return response instanceof ClaimResponse && ((ClaimResponse) response).isRetryable();
    }

    private static boolean isRetryableHttp(int code) {
        return code == 408 || code == 429 || code >= 500;
    }

    private <T> void retry(Request request, Class<T> type, int attemptNumber, CompletableFuture<T> future, String cause) {
        long delay = BASE_BACKOFF_MS * (1L << (attemptNumber - 1));
        log.debug("Retrying bingo request in {}ms (attempt {} failed: {})", delay, attemptNumber, cause);
        executor.schedule(
            () -> attempt(request, type, attemptNumber + 1, future),
            delay,
            TimeUnit.MILLISECONDS
        );
    }
}

package dinkbingo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(BingoConfig.GROUP)
public interface BingoConfig extends Config {

    String GROUP = "dinkbingo";

    @ConfigSection(
        name = "Connection",
        description = "Where the bingo board lives",
        position = 0
    )
    String connectionSection = "Connection";

    @ConfigSection(
        name = "Board Panel",
        description = "How your team's board is displayed",
        position = 10
    )
    String boardSection = "Board Panel";

    @ConfigSection(
        name = "Detection",
        description = "What counts as a bingo drop",
        position = 20
    )
    String detectionSection = "Detection";

    @ConfigSection(
        name = "Announcements",
        description = "How accepted progress and completions are announced via Dink",
        position = 30
    )
    String announceSection = "Announcements";

    // -----------------------------------------------------------------------
    // Connection
    // -----------------------------------------------------------------------

    @ConfigItem(
        keyName = "backendUrl",
        name = "Backend URL",
        description = "The HTTPS Apps Script web app URL for your event (ends in /exec).<br/>" +
            "Nothing is sent anywhere until this is set.",
        position = 1,
        section = connectionSection
    )
    default String backendUrl() {
        return "";
    }

    @ConfigItem(
        keyName = "eventToken",
        name = "Event Token",
        description = "The shared token from your board's Config tab",
        position = 2,
        section = connectionSection,
        secret = true
    )
    default String eventToken() {
        return "";
    }

    @Range(min = 1, max = 60)
    @ConfigItem(
        keyName = "refreshMinutes",
        name = "Refresh Interval (minutes)",
        description = "How often the board is re-fetched so teammates' claims show up",
        position = 3,
        section = connectionSection
    )
    default int refreshMinutes() {
        return 5;
    }

    // -----------------------------------------------------------------------
    // Board panel
    // -----------------------------------------------------------------------

    @ConfigItem(
        keyName = "boardView",
        name = "Board View",
        description = "Show unfinished tile names or every item still eligible for an unfinished tile",
        position = 11,
        section = boardSection
    )
    default BoardView boardView() {
        return BoardView.NAMED_TILES;
    }

    @ConfigItem(
        keyName = "hideCompletedTiles",
        name = "Hide Completed Tiles",
        description = "Hide tiles your team has already completed from the sidebar",
        position = 12,
        section = boardSection
    )
    default boolean hideCompletedTiles() {
        return false;
    }

    // -----------------------------------------------------------------------
    // Detection
    // -----------------------------------------------------------------------

    @ConfigItem(
        keyName = "includeCollectionLog",
        name = "Include Collection Log",
        description = "Also treat a new collection log entry as a bingo drop.<br/>" +
            "Useful for items that are equipped or banked rather than picked up as loot",
        position = 11,
        section = detectionSection
    )
    default boolean includeCollectionLog() {
        return true;
    }

    @ConfigItem(
        keyName = "includePlayerLoot",
        name = "Include PK Loot",
        description = "Whether items taken from other players can claim a tile",
        position = 12,
        section = detectionSection
    )
    default boolean includePlayerLoot() {
        return false;
    }

    // -----------------------------------------------------------------------
    // Announcements
    // -----------------------------------------------------------------------

    @ConfigItem(
        keyName = "sendScreenshot",
        name = "Send Screenshot",
        description = "Ask Dink to attach a screenshot as proof of the drop.<br/>" +
            "Dink's own 'External Plugin Requests > Send Image' setting can override this",
        position = 21,
        section = announceSection
    )
    default boolean sendScreenshot() {
        return true;
    }

    @ConfigItem(
        keyName = "showVerificationOverlay",
        name = "Show Verification Overlay",
        description = "Show the current date, time, time zone, and bingo code in the game view.<br/>" +
            "This remains visible until the setting is turned off",
        position = 22,
        section = announceSection
    )
    default boolean showVerificationOverlay() {
        return false;
    }

    @ConfigItem(
        keyName = "verificationCode",
        name = "Bingo Verification Code",
        description = "The organizer-provided code shown in the verification overlay.<br/>" +
            "Update this at the start of each bingo",
        position = 23,
        section = announceSection
    )
    default String verificationCode() {
        return "";
    }

    @ConfigItem(
        keyName = "bingoWebhook",
        name = "Bingo Webhook Override",
        description = "If non-empty, bingo updates are sent to this Discord webhook.<br/>" +
            "Otherwise Dink's 'External Webhook Override' (or primary URL) is used",
        position = 24,
        section = announceSection,
        secret = true
    )
    default String bingoWebhook() {
        return "";
    }

    @ConfigItem(
        keyName = "notifyMessage",
        name = "Completion Message",
        description = "Used when a contribution completes a tile.<br/>" +
            "%USERNAME%, %ITEM%, %TILE%, %TEAM%, %PROGRESS%, %REQUIRED%, " +
            "%REMAINING% and %SOURCE% are replaced",
        position = 25,
        section = announceSection
    )
    default String notifyMessage() {
        return "%USERNAME% claimed %ITEM% for %TEAM% — %REMAINING% tiles left";
    }

    @ConfigItem(
        keyName = "progressMessage",
        name = "Progress Message",
        description = "Used when a distinct item advances a threshold tile without completing it.<br/>" +
            "%USERNAME%, %ITEM%, %TILE%, %TEAM%, %PROGRESS%, %REQUIRED%, " +
            "%REMAINING% and %SOURCE% are replaced",
        position = 26,
        section = announceSection
    )
    default String progressMessage() {
        return "%USERNAME% added %ITEM% to %TILE% for %TEAM% — %PROGRESS%/%REQUIRED%";
    }

    @ConfigItem(
        keyName = "chatMessageOnClaim",
        name = "Game Chat Confirmation",
        description = "Print the claim result to your game chat so you know it registered",
        position = 27,
        section = announceSection
    )
    default boolean chatMessageOnClaim() {
        return true;
    }
}

package dinkbingo;

import lombok.Value;
import org.jetbrains.annotations.Nullable;

/**
 * One distinct accepted item credited toward a team's logical tile.
 */
@Value
public class BingoContribution {

    int id;

    String name;

    @Nullable
    String claimedBy;

    @Nullable
    String claimedAt;
}

package dinkbingo;

import dinkbingo.BingoResponses.ClaimRequest;
import dinkbingo.BingoResponses.ClaimResponse;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collection;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.CopyOnWriteArraySet;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BiConsumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Owns the board snapshot and decides which drops are worth submitting.
 * <p>
 * Deliberately free of RuneLite event subscriptions so it can be unit tested directly;
 * {@link BingoPlugin} owns the {@code @Subscribe} methods and forwards to here.
 */
@Slf4j
@Singleton
public class BingoDetector {

    private static final Pattern COLLECTION_LOG_PATTERN =
        Pattern.compile("New item added to your collection log: (?<itemName>.*)");

    private final Client client;
    private final ItemManager itemManager;
    private final BingoConfig config;
    private final BingoClient bingoClient;

    @Inject
    public BingoDetector(Client client, ItemManager itemManager, BingoConfig config, BingoClient bingoClient) {
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
        this.bingoClient = bingoClient;
    }

    /** The latest board snapshot; replaced wholesale, never mutated. */
    @Getter
    private volatile BingoBoard board = BingoBoard.EMPTY;

    /**
     * Item ids with a contribution POST in flight. Duplicate events for one item must not both
     * submit, while two different accepted items from one loot event must both be allowed.
     * {@code ServerNpcLoot} and {@code NpcLootReceived} for some NPCs) must not both submit.
     */
    private final Set<Integer> inFlight = new CopyOnWriteArraySet<>();

    /**
     * Item ids the backend has already credited for us this session.
     */
    private final Set<Integer> resolvedItems = new CopyOnWriteArraySet<>();

    /** Logical tiles completed before the refreshed board snapshot arrives. */
    private final Set<String> resolvedTiles = new CopyOnWriteArraySet<>();
    private final AtomicLong generation = new AtomicLong();

    /**
     * Invoked with the response and the loot source for every submitted claim, on the
     * executor thread. The source is carried through rather than read from shared state,
     * because another drop can land during the backend round trip.
     */
    private volatile BiConsumer<ClaimResponse, String> claimListener = (res, source) -> {
    };

    public void setClaimListener(BiConsumer<ClaimResponse, String> listener) {
        this.claimListener = listener;
    }

    public void setBoard(BingoBoard board) {
        this.board = board;
        // The sheet is authoritative. If an organizer unclaimed a tile, allow this client
        // to submit it again instead of retaining the session-local resolved marker.
        this.resolvedItems.removeAll(board.getOpenItemIds());
        this.resolvedTiles.removeAll(board.getRemaining());
    }

    public void reset() {
        this.generation.incrementAndGet();
        this.board = BingoBoard.EMPTY;
        this.inFlight.clear();
        this.resolvedItems.clear();
        this.resolvedTiles.clear();
    }

    // ------------------------------------------------------------------
    // detection entry points
    // ------------------------------------------------------------------

    public void onLoot(Collection<ItemStack> items, String source) {
        if (items == null || !bingoClient.isConfigured()) {
            return;
        }
        for (ItemStack item : items) {
            // Un-notes, un-placeholders and un-wears so board ids match what actually dropped.
            int canonical = itemManager.canonicalize(item.getId());
            submitIfClaimable(canonical, Math.max(1, item.getQuantity()), source);
        }
    }

    public void onGameMessage(String message) {
        if (!config.includeCollectionLog() || !bingoClient.isConfigured()) {
            return;
        }
        Matcher matcher = COLLECTION_LOG_PATTERN.matcher(message);
        if (!matcher.find()) {
            return;
        }

        // The board already carries item names, so match on those rather than maintaining a
        // separate name -> id index just for this path.
        String itemName = matcher.group("itemName").trim();
        for (BingoTile tile : board.getTiles()) {
            for (BingoItem option : tile.getOptions()) {
                if (option.getName().equalsIgnoreCase(itemName)) {
                    submitIfClaimable(option.getId(), 1, "Collection log");
                    return;
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // claim submission
    // ------------------------------------------------------------------

    boolean shouldSubmit(int itemId) {
        BingoTile tile = board.getByItemId().get(itemId);
        return board.isClaimable(itemId)
            && tile != null
            && !inFlight.contains(itemId)
            && !resolvedItems.contains(itemId)
            && !resolvedTiles.contains(tile.getId());
    }

    private void submitIfClaimable(int itemId, int quantity, String source) {
        if (!shouldSubmit(itemId)) {
            return;
        }
        BingoTile tile = board.getByItemId().get(itemId);
        if (tile == null || !inFlight.add(itemId)) {
            return; // lost the race against another event for this exact item
        }

        BingoItem option = board.findOption(itemId);
        ClaimRequest claim = new ClaimRequest();
        claim.setRsn(getPlayerName());
        claim.setItemId(itemId);
        claim.setItemName(option != null ? option.getName() : String.valueOf(itemId));
        claim.setQuantity(quantity);
        claim.setSource(source != null ? source : "");
        claim.setClaimId(UUID.randomUUID().toString());
        long claimGeneration = generation.get();

        log.debug("Submitting bingo claim for {} ({}) from {}", claim.getItemName(), itemId, source);

        bingoClient.submitClaim(claim).whenComplete((response, error) -> {
            try {
                if (claimGeneration != generation.get()) {
                    return; // plugin reset, logout, or configuration change while request was in flight
                }
                if (error != null || response == null) {
                    // Unresolved: allow a later drop of the same item to try again.
                    log.debug("Bingo claim for {} did not resolve", itemId, error);
                    return;
                }
                if (response.isResolvedOutcome()) {
                    if (response.isComplete()) {
                        resolvedTiles.add(tile.getId());
                    } else {
                        resolvedItems.add(itemId);
                    }
                }
                claimListener.accept(response, claim.getSource());
            } finally {
                inFlight.remove(itemId);
            }
        });
    }

    private String getPlayerName() {
        return client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
    }
}

package dinkbingo;

import lombok.Value;

/**
 * One actual item that can satisfy a logical bingo tile.
 */
@Value
public class BingoItem {

    int id;

    String name;
}

package dinkbingo;

import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.SwingUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.util.HashSet;
import java.util.Set;
import java.util.StringJoiner;

/**
 * Side panel showing the team's board: which tiles are still open, and who took the rest.
 */
@Singleton
public class BingoPanel extends PluginPanel {

    private static final Color CLAIMED_COLOR = new Color(0x7A, 0x7A, 0x7A);
    private static final Color OPEN_COLOR = Color.WHITE;

    private final ItemManager itemManager;

    private final JLabel headerLabel = new JLabel();
    private final JLabel statusLabel = new JLabel();
    private final JPanel itemsPanel = new JPanel();
    private final JScrollPane itemsScrollPane = new JScrollPane(
        itemsPanel,
        ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
        ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER
    );
    private final JButton refreshButton = new JButton("Refresh");

    private Runnable refreshHandler = () -> {
    };

    @Inject
    BingoPanel(ItemManager itemManager) {
        super(false);
        this.itemManager = itemManager;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

        headerLabel.setFont(FontManager.getRunescapeBoldFont());
        headerLabel.setForeground(Color.WHITE);
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        JPanel titles = new JPanel();
        titles.setLayout(new BoxLayout(titles, BoxLayout.Y_AXIS));
        titles.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titles.add(headerLabel);
        titles.add(statusLabel);

        refreshButton.setFocusPainted(false);
        refreshButton.addActionListener(e -> refreshHandler.run());

        header.add(titles, BorderLayout.CENTER);
        header.add(refreshButton, BorderLayout.EAST);

        itemsPanel.setLayout(new GridBagLayout());
        itemsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        itemsScrollPane.setBorder(BorderFactory.createEmptyBorder());
        itemsScrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        itemsScrollPane.getVerticalScrollBar().setUnitIncrement(16);

        add(header, BorderLayout.NORTH);
        add(itemsScrollPane, BorderLayout.CENTER);
    }

    public void setRefreshHandler(Runnable handler) {
        this.refreshHandler = handler;
    }

    /** Safe to call from any thread. */
    public void render(
        BingoBoard board,
        boolean configured,
        BoardView boardView,
        boolean hideCompletedTiles
    ) {
        SwingUtilities.invokeLater(() ->
            renderOnEdt(board, configured, boardView, hideCompletedTiles));
    }

    /** Safe to call from any thread. */
    public void renderLoading() {
        SwingUtilities.invokeLater(() -> renderMessage(
            "Loading board",
            "Fetching your team's tiles\u2026"
        ));
    }

    /** Safe to call from any thread. */
    public void renderLoadError() {
        SwingUtilities.invokeLater(() -> renderMessage(
            "Couldn't load board",
            "Check your connection, then press Refresh"
        ));
    }

    private void renderOnEdt(
        BingoBoard board,
        boolean configured,
        BoardView boardView,
        boolean hideCompletedTiles
    ) {
        SwingUtil.fastRemoveAll(itemsPanel);

        if (!configured) {
            headerLabel.setText("Not configured");
            statusLabel.setText("Set a Backend URL in the config");
            refreshItemsPanel();
            return;
        }

        if (!board.isConfigured()) {
            headerLabel.setText("No team");
            statusLabel.setText("Your RSN is not on the Teams tab");
            refreshItemsPanel();
            return;
        }

        headerLabel.setText(board.getTeam());
        statusLabel.setText(board.getRemainingCount() + " of " + board.getTiles().size() + " tiles left"
            + (board.isEventOpen() ? "" : " (event closed)"));

        GridBagConstraints c = new GridBagConstraints();
        c.fill = GridBagConstraints.HORIZONTAL;
        c.gridx = 0;
        c.gridy = 0;
        c.weightx = 1;

        if (boardView == BoardView.POSSIBLE_ITEMS) {
            for (BingoTile tile : board.getTiles()) {
                if (tile.isClaimed()) {
                    continue;
                }
                Set<Integer> creditedIds = creditedIds(tile);
                for (BingoItem option : tile.getOptions()) {
                    if (!creditedIds.contains(option.getId())) {
                        itemsPanel.add(buildItemRow(tile, option), c);
                        c.gridy++;
                    }
                }
            }
        } else {
            for (BingoTile tile : board.getTiles()) {
                if (hideCompletedTiles && tile.isClaimed()) {
                    continue;
                }
                itemsPanel.add(buildTileRow(tile), c);
                c.gridy++;
            }
        }

        refreshItemsPanel();
    }

    private void renderMessage(String header, String status) {
        SwingUtil.fastRemoveAll(itemsPanel);
        headerLabel.setText(header);
        statusLabel.setText(status);
        refreshItemsPanel();
    }

    private void refreshItemsPanel() {
        itemsPanel.revalidate();
        itemsPanel.repaint();
    }

    private JPanel buildTileRow(BingoTile tile) {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

        JLabel icon = new JLabel();
        icon.setPreferredSize(new Dimension(36, 32));
        Set<Integer> creditedIds = creditedIds(tile);
        BingoItem iconItem = tile.getClaimedItem();
        if (iconItem == null) {
            for (BingoItem option : tile.getOptions()) {
                if (!creditedIds.contains(option.getId())) {
                    iconItem = option;
                    break;
                }
            }
        }
        if (iconItem != null) {
            AsyncBufferedImage image = itemManager.getImage(iconItem.getId());
            image.addTo(icon);
        }
        row.add(icon, BorderLayout.WEST);

        JLabel name = new JLabel();
        name.setFont(FontManager.getRunescapeSmallFont());
        if (tile.isClaimed()) {
            String winner = tile.getClaimedItem() != null ? tile.getClaimedItem().getName() : null;
            // Strikethrough via HTML is the only way to get it on a plain JLabel.
            name.setText("<html><s>" + escape(tile.getName()) + "</s></html>");
            name.setForeground(CLAIMED_COLOR);
            name.setToolTipText("Claimed by " + tile.getClaimedBy() +
                (winner == null ? "" : " with " + winner));
        } else {
            name.setText(tile.getName());
            name.setForeground(OPEN_COLOR);
            StringJoiner credited = new StringJoiner(", ");
            for (BingoContribution contribution : tile.getClaimedItems()) {
                credited.add(contribution.getName());
            }
            StringJoiner missing = new StringJoiner(", ");
            for (BingoItem option : tile.getOptions()) {
                if (!creditedIds.contains(option.getId())) missing.add(option.getName());
            }
            name.setToolTipText((tile.getClaimedItems().isEmpty() ? "" :
                "Credited: " + credited + ". ") + "Still eligible: " + missing);
        }
        row.add(name, BorderLayout.CENTER);

        if (tile.isClaimed() && tile.getClaimedBy() != null) {
            JLabel by = new JLabel(tile.getClaimedBy());
            by.setFont(FontManager.getRunescapeSmallFont());
            by.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
            row.add(by, BorderLayout.EAST);
        } else if (tile.getRequired() > 1 || tile.getProgress() > 0) {
            JLabel progress = new JLabel(tile.getProgress() + "/" + tile.getRequired());
            progress.setFont(FontManager.getRunescapeSmallFont());
            progress.setForeground(ColorScheme.PROGRESS_INPROGRESS_COLOR);
            row.add(progress, BorderLayout.EAST);
        }

        return row;
    }

    private JPanel buildItemRow(BingoTile tile, BingoItem option) {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

        JLabel icon = new JLabel();
        icon.setPreferredSize(new Dimension(36, 32));
        itemManager.getImage(option.getId()).addTo(icon);
        row.add(icon, BorderLayout.WEST);

        JLabel name = new JLabel(option.getName());
        name.setFont(FontManager.getRunescapeSmallFont());
        name.setForeground(OPEN_COLOR);
        name.setToolTipText("Eligible for " + tile.getName());
        row.add(name, BorderLayout.CENTER);

        if (tile.getRequired() > 1 || tile.getProgress() > 0) {
            JLabel progress = new JLabel(tile.getProgress() + "/" + tile.getRequired());
            progress.setFont(FontManager.getRunescapeSmallFont());
            progress.setForeground(ColorScheme.PROGRESS_INPROGRESS_COLOR);
            progress.setToolTipText(tile.getName());
            row.add(progress, BorderLayout.EAST);
        }

        return row;
    }

    private static Set<Integer> creditedIds(BingoTile tile) {
        Set<Integer> creditedIds = new HashSet<>();
        for (BingoContribution contribution : tile.getClaimedItems()) {
            creditedIds.add(contribution.getId());
        }
        return creditedIds;
    }

    private static String escape(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package dinkbingo;

import com.google.inject.Provides;
import dinkbingo.BingoResponses.ClaimResponse;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.loottracker.LootRecordType;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

@Slf4j
@PluginDescriptor(
    name = "Bingo with Dink Notifications",
    description = "Claims bingo tiles on a shared board when you get the drop, and announces via Dink",
    tags = {"bingo", "dink", "loot", "clan", "event", "collection", "discord"}
)
public class BingoPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private BingoConfig config;

    @Inject
    private BingoClient bingoClient;

    @Inject
    private BingoDetector detector;

    @Inject
    private BingoAnnouncer announcer;

    @Inject
    private BingoPanel panel;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BingoVerificationOverlay verificationOverlay;

    private NavigationButton navButton;
    private ScheduledFuture<?> refreshTask;
    private final AtomicLong lifecycleGeneration = new AtomicLong();
    private final AtomicLong refreshGeneration = new AtomicLong();
    private final Object refreshStateLock = new Object();
    private volatile boolean active;
    private boolean refreshInFlight;
    private boolean refreshPending;
    private long inFlightLifecycle;
    private long inFlightRefresh;
    private volatile BingoBoard currentBoard = BingoBoard.EMPTY;
    private volatile boolean boardLoaded;

    @Provides
    BingoConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(BingoConfig.class);
    }

    @Override
    protected void startUp() {
        active = true;
        lifecycleGeneration.incrementAndGet();
        refreshGeneration.incrementAndGet();
        synchronized (refreshStateLock) {
            refreshInFlight = false;
            refreshPending = false;
            inFlightLifecycle = 0;
            inFlightRefresh = 0;
        }
        currentBoard = BingoBoard.EMPTY;
        boardLoaded = false;
        detector.setClaimListener(this::onClaimResolved);
        overlayManager.add(verificationOverlay);

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/bingo_icon.png");
        navButton = NavigationButton.builder()
            .tooltip("Bingo with Dink Notifications")
            .icon(icon)
            .priority(7)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);

        panel.setRefreshHandler(this::refreshBoard);
        if (bingoClient.isConfigured()) {
            panel.renderLoading();
        } else {
            renderBoard(BingoBoard.EMPTY, false);
        }

        scheduleRefresh();
        refreshBoard();
    }

    @Override
    protected void shutDown() {
        active = false;
        lifecycleGeneration.incrementAndGet();
        refreshGeneration.incrementAndGet();
        synchronized (refreshStateLock) {
            refreshPending = false;
        }
        if (refreshTask != null) {
            refreshTask.cancel(false);
            refreshTask = null;
        }
        if (navButton != null) {
            clientToolbar.removeNavigation(navButton);
        }
        navButton = null;
        overlayManager.remove(verificationOverlay);
        panel.setRefreshHandler(() -> {
        });
        detector.setClaimListener((response, source) -> {
        });
        detector.reset();
    }

    // ------------------------------------------------------------------
    // board lifecycle
    // ------------------------------------------------------------------

    private void scheduleRefresh() {
        if (refreshTask != null) {
            refreshTask.cancel(false);
        }
        if (!active) {
            return;
        }
        long minutes = Math.max(1, config.refreshMinutes());
        refreshTask = executor.scheduleWithFixedDelay(
            this::refreshBoard, minutes, minutes, TimeUnit.MINUTES);
    }

    void refreshBoard() {
        if (!active) {
            return;
        }
        long lifecycle = lifecycleGeneration.get();
        long refresh = refreshGeneration.incrementAndGet();
        clientThread.invokeLater(() -> beginRefresh(lifecycle, refresh));
    }

    private void beginRefresh(long lifecycle, long requestedRefresh) {
        if (!isCurrent(lifecycle) || requestedRefresh != refreshGeneration.get()) {
            return;
        }
        if (!bingoClient.isConfigured()) {
            currentBoard = BingoBoard.EMPTY;
            boardLoaded = false;
            detector.reset();
            renderBoard(BingoBoard.EMPTY, false);
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) {
            return;
        }

        String rsn = client.getLocalPlayer().getName();
        long fetchRefresh;
        synchronized (refreshStateLock) {
            if (refreshInFlight) {
                refreshPending = true;
                return;
            }
            refreshInFlight = true;
            fetchRefresh = refreshGeneration.get();
            inFlightLifecycle = lifecycle;
            inFlightRefresh = fetchRefresh;
        }

        bingoClient.fetchBoard(rsn).whenComplete((board, error) ->
            finishRefresh(lifecycle, fetchRefresh, board, error));
    }

    private void finishRefresh(long lifecycle, long fetchRefresh, BingoBoard board, Throwable error) {
        boolean rerun;
        synchronized (refreshStateLock) {
            if (!refreshInFlight
                || inFlightLifecycle != lifecycle
                || inFlightRefresh != fetchRefresh) {
                return;
            }
            refreshInFlight = false;
            rerun = refreshPending;
            refreshPending = false;
        }

        if (isCurrent(lifecycle)
            && fetchRefresh == refreshGeneration.get()
            && error == null
            && board != null) {
            currentBoard = board;
            boardLoaded = true;
            detector.setBoard(board);
            renderBoard(board, true);
        } else if (isCurrent(lifecycle)
            && fetchRefresh == refreshGeneration.get()
            && !boardLoaded) {
            panel.renderLoadError();
        }
        if (rerun && active) {
            refreshBoard();
        }
    }

    private boolean isCurrent(long lifecycle) {
        return active && lifecycle == lifecycleGeneration.get();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            // The local player is not populated the instant the state flips.
            refreshBoard();
        } else if (event.getGameState() == GameState.LOGIN_SCREEN) {
            refreshGeneration.incrementAndGet();
            currentBoard = BingoBoard.EMPTY;
            boardLoaded = false;
            detector.reset();
            if (bingoClient.isConfigured()) {
                panel.renderLoading();
            }
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!BingoConfig.GROUP.equals(event.getGroup())) {
            return;
        }
        if ("refreshMinutes".equals(event.getKey())) {
            scheduleRefresh();
        }
        if ("backendUrl".equals(event.getKey()) || "eventToken".equals(event.getKey())) {
            currentBoard = BingoBoard.EMPTY;
            boardLoaded = false;
            detector.reset();
            if (bingoClient.isConfigured()) {
                panel.renderLoading();
            }
            refreshBoard();
        } else if (("boardView".equals(event.getKey())
            || "hideCompletedTiles".equals(event.getKey())) && boardLoaded) {
            renderBoard(currentBoard, true);
        }
    }

    private void renderBoard(BingoBoard board, boolean configured) {
        panel.render(board, configured, config.boardView(), config.hideCompletedTiles());
    }

    // ------------------------------------------------------------------
    // detection
    // ------------------------------------------------------------------

    @Subscribe
    public void onServerNpcLoot(ServerNpcLoot event) {
        detector.onLoot(event.getItems(), event.getComposition().getName());
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        NPC npc = event.getNpc();
        detector.onLoot(event.getItems(), npc.getName());
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event) {
        if (!config.includePlayerLoot()) {
            return;
        }
        detector.onLoot(event.getItems(), event.getPlayer().getName());
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        // PK loot is gated behind its own config setting and arrives via PlayerLootReceived.
        if (event.getType() == LootRecordType.PLAYER) {
            return;
        }
        // Everything else is accepted, including LootRecordType.NPC. That overlaps with
        // ServerNpcLoot/NpcLootReceived above, but the detector dedupes per item id, and
        // upstream has historically moved individual bosses (Gauntlet, Whisperer, Araxxor)
        // between these events — a missed tile is far worse than a redundant event.
        detector.onLoot(event.getItems(), event.getName());
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }
        detector.onGameMessage(event.getMessage());
    }

    // ------------------------------------------------------------------
    // claim results
    // ------------------------------------------------------------------

    private void onClaimResolved(ClaimResponse response, String source) {
        if (response == null) {
            return;
        }
        long lifecycle = lifecycleGeneration.get();
        clientThread.invokeLater(() -> handleClaimResolved(lifecycle, response, source));
    }

    private void handleClaimResolved(long lifecycle, ClaimResponse response, String source) {
        if (!isCurrent(lifecycle)) {
            return;
        }
        announcer.announce(response, source);

        if (config.chatMessageOnClaim()) {
            sendChatMessage(describe(response));
        }

        // Re-fetch so the panel and the remaining set reflect the new state, including any
        // tiles teammates claimed while we were busy.
        refreshBoard();
    }

    private String describe(ClaimResponse response) {
        String item = response.getItemName() != null ? response.getItemName() : "That item";
        String tile = response.getTileName();
        String claimLabel = tile != null && !tile.equalsIgnoreCase(item) ?
            item + " for the " + tile + " tile" : item;
        switch (response.getStatus()) {
            case BingoResponses.CLAIMED:
                return "Bingo: completed " + claimLabel + " for " + response.getTeam()
                    + " (" + response.getRemaining() + " tiles left).";
            case BingoResponses.PROGRESS:
                return "Bingo: added " + item + " to the " + (tile != null ? tile : item)
                    + " tile for " + response.getTeam() + " (" + response.getProgress()
                    + "/" + response.getRequired() + ").";
            case BingoResponses.DUPLICATE:
                return response.isComplete()
                    ? "Bingo: the " + (tile != null ? tile : item) + " tile is already complete."
                    : "Bingo: " + item + " is already credited to the "
                        + (tile != null ? tile : item) + " tile.";
            case BingoResponses.NOT_ON_TEAM:
                return "Bingo: your RSN is not on the Teams tab, so nothing was claimed.";
            case BingoResponses.EVENT_CLOSED:
                return "Bingo: the event is not currently open, so nothing was claimed.";
            case BingoResponses.NOT_ON_BOARD:
                return "Bingo: " + item + " is not on the board.";
            default:
                return "Bingo: claim failed (" + response.getStatus() + ").";
        }
    }

    private void sendChatMessage(String message) {
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(ColorUtil.wrapWithColorTag(message, new Color(0x00, 0xB0, 0x50)))
            .build());
    }
}

package dinkbingo;

import lombok.Data;
import org.jetbrains.annotations.Nullable;

import java.util.List;

/**
 * Wire types for the Apps Script backend. Deserialized by Gson, so these are mutable
 * beans with field names matching the JSON exactly.
 */
public class BingoResponses {

    private BingoResponses() {
    }

    /** Outcomes of a claim attempt. Accepted progress and completion trigger announcements. */
    public static final String CLAIMED = "claimed";
    public static final String PROGRESS = "progress";
    public static final String DUPLICATE = "duplicate";
    public static final String NOT_ON_BOARD = "not_on_board";
    public static final String NOT_ON_TEAM = "not_on_team";
    public static final String EVENT_CLOSED = "event_closed";
    public static final String ERROR = "error";

    @Data
    public static class BoardRequest {
        String action;
        String token;
        String rsn;
    }

    @Data
    public static class BoardResponse {
        String status;
        @Nullable
        String team;
        int remaining;
        int total;
        boolean eventOpen;
        @Nullable
        List<BoardTile> tiles;
        @Nullable
        String error;
    }

    @Data
    public static class BoardTile {
        String id;
        String name;
        int points;
        int required;
        int progress;
        boolean claimed;
        @Nullable
        String claimedBy;
        @Nullable
        String claimedAt;
        @Nullable
        BoardItem claimedItem;
        @Nullable
        List<BoardClaimedItem> claimedItems;
        @Nullable
        List<BoardItem> options;
    }

    @Data
    public static class BoardItem {
        int id;
        String name;
    }

    @Data
    public static class BoardClaimedItem {
        int id;
        String name;
        @Nullable
        String claimedBy;
        @Nullable
        String claimedAt;
    }

    @Data
    public static class ClaimRequest {
        String token;
        String rsn;
        int itemId;
        String itemName;
        int quantity;
        String source;
        String claimId;
    }

    @Data
    public static class ClaimResponse {
        String status;
        boolean replay;
        @Nullable
        String team;
        @Nullable
        String tileId;
        @Nullable
        String tileName;
        int itemId;
        @Nullable
        String itemName;
        int points;
        int progress;
        int required;
        boolean complete;
        int remaining;
        int total;
        @Nullable
        String claimedBy;
        @Nullable
        String claimedAt;
        @Nullable
        List<BoardClaimedItem> claimedItems;
        @Nullable
        String error;
        boolean retryable;

        public boolean isClaimed() {
            return CLAIMED.equals(status);
        }

        public boolean isProgress() {
            return PROGRESS.equals(status);
        }

        public boolean isAnnounceable() {
            return isClaimed() || isProgress();
        }

        public boolean isResolvedOutcome() {
            return CLAIMED.equals(status)
                || PROGRESS.equals(status)
                || DUPLICATE.equals(status)
                || NOT_ON_BOARD.equals(status)
                || NOT_ON_TEAM.equals(status)
                || EVENT_CLOSED.equals(status);
        }
    }
}

package dinkbingo;

import lombok.Value;
