package dinkbingo;

import dinkbingo.BingoResponses.ClaimResponse;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import okhttp3.HttpUrl;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class BingoAnnouncerTest {

    @Mock
    private EventBus eventBus;

    @Mock
    private BingoConfig config;

    private BingoAnnouncer announcer;

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);
        when(config.notifyMessage()).thenReturn("%USERNAME% claimed %ITEM% for %TEAM% — %REMAINING% tiles left");
        when(config.progressMessage()).thenReturn(
            "%USERNAME% added %ITEM% to %TILE% for %TEAM% — %PROGRESS%/%REQUIRED%");
        when(config.sendScreenshot()).thenReturn(true);
        when(config.bingoWebhook()).thenReturn("");

        announcer = new BingoAnnouncer(eventBus, config);
    }

    @Test
    void postsADinkNotifyMessageForAClaim() {
        announcer.announce(claim(BingoResponses.CLAIMED), "Abyssal demon");

        PluginMessage message = capture();
        assertEquals("dink", message.getNamespace());
        assertEquals("notify", message.getName());

        Map<String, Object> data = message.getData();
        assertEquals("Bingo with Dink Notifications", data.get("sourcePlugin"));
        assertEquals("Bingo tile completed", data.get("title"));
        assertEquals(true, data.get("imageRequested"));
        assertEquals("https://static.runelite.net/cache/item/icon/4151.png", data.get("thumbnail"));
        assertTrue(String.valueOf(data.get("text")).contains("%ITEM%"));
    }

    @Test
    void suppliesReplacementsForEveryTemplateToken() {
        announcer.announce(claim(BingoResponses.CLAIMED), "Abyssal demon");

        @SuppressWarnings("unchecked")
        Map<String, Map<String, String>> replacements =
            (Map<String, Map<String, String>>) capture().getData().get("replacements");

        assertEquals("Abyssal whip", replacements.get("%ITEM%").get("value"));
        assertTrue(replacements.get("%ITEM%").get("richValue").contains("oldschool.runescape.wiki"));
        assertEquals("Any rare drop", replacements.get("%TILE%").get("value"));
        assertEquals("Team One", replacements.get("%TEAM%").get("value"));
        assertEquals("2", replacements.get("%PROGRESS%").get("value"));
        assertEquals("2", replacements.get("%REQUIRED%").get("value"));
        assertEquals("3", replacements.get("%REMAINING%").get("value"));
        assertEquals("Abyssal demon", replacements.get("%SOURCE%").get("value"));
    }

    @Test
    void includesTheLogicalTileAndWinningItemAsEvidence() {
        announcer.announce(claim(BingoResponses.CLAIMED), "Abyssal demon");

        Map<String, Object> data = capture().getData();
        @SuppressWarnings("unchecked")
        List<Map<String, Object>> fields = (List<Map<String, Object>>) data.get("fields");
        assertTrue(fields.stream().anyMatch(field ->
            "Bingo Tile".equals(field.get("name")) && "Any rare drop".equals(field.get("value"))));
        assertTrue(fields.stream().anyMatch(field ->
            "Completing Item".equals(field.get("name")) && "Abyssal whip".equals(field.get("value"))));
        assertTrue(fields.stream().anyMatch(field ->
            "Progress".equals(field.get("name")) && "2 / 2".equals(field.get("value"))));
        assertTrue(fields.stream().anyMatch(field ->
            "Credited Items".equals(field.get("name"))
                && "Bandos chestplate, Abyssal whip".equals(field.get("value"))));
    }

    @Test
    void postsADinkNotifyMessageForAcceptedProgress() {
        ClaimResponse response = claim(BingoResponses.PROGRESS);
        response.setProgress(1);
        response.setComplete(false);
        response.setPoints(0);

        announcer.announce(response, "Abyssal demon");

        Map<String, Object> data = capture().getData();
        assertEquals("Bingo tile progress", data.get("title"));
        assertEquals(config.progressMessage(), data.get("text"));
        @SuppressWarnings("unchecked")
        Map<String, Object> metadata = (Map<String, Object>) data.get("metadata");
        assertEquals(0, metadata.get("points"));
        @SuppressWarnings("unchecked")
        List<Map<String, Object>> fields = (List<Map<String, Object>>) data.get("fields");
        assertTrue(fields.stream().anyMatch(field ->
            "Contributed Item".equals(field.get("name")) && "Abyssal whip".equals(field.get("value"))));
    }

    /** Dink drops the entire request unless every url is an okhttp3.HttpUrl instance. */
    @Test
    void passesWebhookOverrideAsHttpUrlInstances() {
        when(config.bingoWebhook()).thenReturn("https://discord.com/api/webhooks/a/b");

        announcer.announce(claim(BingoResponses.CLAIMED), "Abyssal demon");

        Object urls = capture().getData().get("urls");
        assertTrue(urls instanceof List);
        for (Object url : (List<?>) urls) {
            assertTrue(url instanceof HttpUrl, "Dink rejects url entries that are not HttpUrl");
        }
    }

    @Test
    void omitsUrlsWhenNoOverrideIsSet() {
        announcer.announce(claim(BingoResponses.CLAIMED), "Abyssal demon");
        assertFalse(capture().getData().containsKey("urls"));
    }

    @Test
    void omitsAnInsecureWebhookOverride() {
        when(config.bingoWebhook()).thenReturn("http://example.com/webhook");
        announcer.announce(claim(BingoResponses.CLAIMED), "Abyssal demon");
        assertFalse(capture().getData().containsKey("urls"));
    }

    @Test
    void doesNotAnnounceADuplicate() {
        announcer.announce(claim(BingoResponses.DUPLICATE), "Abyssal demon");
        verify(eventBus, never()).post(any());
    }

    @Test
    void doesNotAnnounceWhenTheRsnIsNotOnATeam() {
        announcer.announce(claim(BingoResponses.NOT_ON_TEAM), "Abyssal demon");
        verify(eventBus, never()).post(any());
    }

    @Test
    void announcesAReplayReturnedToTheOriginalInFlightClaim() {
        ClaimResponse response = claim(BingoResponses.CLAIMED);
        response.setReplay(true);

        announcer.announce(response, "Abyssal demon");

        assertEquals("notify", capture().getName());
    }

    @Test
    void toleratesANullResponse() {
        announcer.announce(null, "Abyssal demon");
        verify(eventBus, never()).post(any());
    }

    // ------------------------------------------------------------------

    private PluginMessage capture() {
        ArgumentCaptor<PluginMessage> captor = ArgumentCaptor.forClass(PluginMessage.class);
        verify(eventBus).post(captor.capture());
        return captor.getValue();
    }

    private static ClaimResponse claim(String status) {
        ClaimResponse response = new ClaimResponse();
        response.setStatus(status);
        response.setTeam("Team One");
        response.setTileId("rare-drop");
        response.setTileName("Any rare drop");
        response.setItemId(4151);
        response.setItemName("Abyssal whip");
        response.setPoints(1);
        response.setProgress(2);
        response.setRequired(2);
        response.setComplete(true);
        response.setRemaining(3);
        response.setTotal(10);
        BingoResponses.BoardClaimedItem first = new BingoResponses.BoardClaimedItem();
        first.setId(11832);
        first.setName("Bandos chestplate");
        BingoResponses.BoardClaimedItem second = new BingoResponses.BoardClaimedItem();
        second.setId(4151);
        second.setName("Abyssal whip");
        response.setClaimedItems(java.util.Arrays.asList(first, second));
        return response;
    }
}

package dinkbingo;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import dinkbingo.BingoResponses.ClaimRequest;
import dinkbingo.BingoResponses.ClaimResponse;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.io.IOException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.when;

class BingoClientTest {

    private MockWebServer server;
    private ScheduledExecutorService executor;

    @Mock
    private BingoConfig config;

    private BingoClient client;

    @BeforeEach
    void setUp() throws IOException {
        MockitoAnnotations.openMocks(this);

        server = new MockWebServer();
        server.start();
        executor = Executors.newScheduledThreadPool(2);

        when(config.backendUrl()).thenReturn(server.url("/exec").toString());
        when(config.eventToken()).thenReturn("secret-token");

        client = new BingoClient(new OkHttpClient(), new Gson(), executor, config);
    }

    @AfterEach
    void tearDown() throws IOException {
        server.shutdown();
        executor.shutdownNow();
    }

    @Test
    void isNotConfiguredWithoutABackendUrl() {
        when(config.backendUrl()).thenReturn("  ");
        assertFalse(client.isConfigured());
    }

    @Test
    void isNotConfiguredWithAnUnparseableUrl() {
        when(config.backendUrl()).thenReturn("not a url");
        assertFalse(client.isConfigured());
    }

    @Test
    void rejectsPlainHttpExceptForLoopbackDevelopmentServers() {
        when(config.backendUrl()).thenReturn("http://example.com/exec");
        assertFalse(client.isConfigured());
    }

    @Test
    void fetchesAndParsesTheBoard() throws Exception {
        server.enqueue(json("{\"status\":\"ok\",\"team\":\"Team One\",\"remaining\":1,\"total\":2," +
            "\"eventOpen\":true,\"tiles\":[" +
            "{\"id\":\"rare-drop\",\"name\":\"Any rare drop\",\"points\":1,\"required\":2,\"progress\":1,\"claimed\":false," +
            "\"claimedItems\":[{\"id\":4151,\"name\":\"Abyssal whip\",\"claimedBy\":\"Jake\"}]," +
            "\"options\":[{\"id\":4151,\"name\":\"Abyssal whip\"},{\"id\":11832,\"name\":\"Bandos chestplate\"}]}," +
            "{\"id\":\"21034\",\"name\":\"Dexterous prayer scroll\",\"points\":2,\"required\":1,\"progress\":1,\"claimed\":true," +
            "\"claimedBy\":\"Someone\",\"claimedItem\":{\"id\":21034,\"name\":\"Dexterous prayer scroll\"}," +
            "\"claimedItems\":[{\"id\":21034,\"name\":\"Dexterous prayer scroll\",\"claimedBy\":\"Someone\"}]," +
            "\"options\":[{\"id\":21034,\"name\":\"Dexterous prayer scroll\"}]}]}"));

        BingoBoard board = client.fetchBoard("Jake").get(5, TimeUnit.SECONDS);

        assertEquals("Team One", board.getTeam());
        assertTrue(board.isEventOpen());
        assertEquals(2, board.getTiles().size());
        assertEquals(1, board.getRemainingCount());
        assertFalse(board.isClaimable(4151), "an already-credited option is not claimable");
        assertTrue(board.isClaimable(11832), "an uncredited option can advance a partial tile");
        assertFalse(board.isClaimable(21034), "an already-claimed tile is not claimable");
        assertEquals(2, board.getByItemId().get(4151).getRequired());
        assertEquals(1, board.getByItemId().get(4151).getProgress());
        assertEquals("Jake", board.getByItemId().get(4151).getClaimedItems().get(0).getClaimedBy());
        assertEquals("Someone", board.getByItemId().get(21034).getClaimedBy());
        assertEquals("rare-drop", board.getByItemId().get(4151).getId());

        RecordedRequest request = server.takeRequest();
        assertEquals("POST", request.getMethod());
        JsonObject body = new JsonParser().parse(request.getBody().readUtf8()).getAsJsonObject();
        assertEquals("board", body.get("action").getAsString());
        assertEquals("secret-token", body.get("token").getAsString());
        assertEquals("Jake", body.get("rsn").getAsString());
    }

    @Test
    void preservesTheCurrentBoardWhenTheBackendRejectsTheToken() throws Exception {
        server.enqueue(json("{\"status\":\"error\",\"error\":\"bad_token\",\"tiles\":[]}"));

        BingoBoard board = client.fetchBoard("Jake").get(5, TimeUnit.SECONDS);

        assertNull(board);
    }

    @Test
    void postsTheClaimWithTokenAndIdempotencyKey() throws Exception {
        server.enqueue(json("{\"status\":\"claimed\",\"team\":\"Team One\",\"tileId\":\"rare-drop\"," +
            "\"tileName\":\"Any rare drop\",\"itemId\":4151," +
            "\"itemName\":\"Abyssal whip\",\"progress\":2,\"required\":2,\"complete\":true," +
            "\"claimedItems\":[{\"id\":11832,\"name\":\"Bandos chestplate\"},{\"id\":4151,\"name\":\"Abyssal whip\"}]," +
            "\"remaining\":3,\"total\":4}"));

        ClaimResponse response = client.submitClaim(claim()).get(5, TimeUnit.SECONDS);

        assertTrue(response.isClaimed());
        assertEquals("Team One", response.getTeam());
        assertEquals("rare-drop", response.getTileId());
        assertEquals(2, response.getProgress());
        assertEquals(2, response.getRequired());
        assertTrue(response.isComplete());
        assertEquals(2, response.getClaimedItems().size());
        assertEquals(3, response.getRemaining());

        RecordedRequest request = server.takeRequest();
        assertEquals("POST", request.getMethod());
        JsonObject body = new JsonParser().parse(request.getBody().readUtf8()).getAsJsonObject();
        assertEquals("secret-token", body.get("token").getAsString(), "the client injects the configured token");
        assertEquals(4151, body.get("itemId").getAsInt());
        assertEquals("claim-abc", body.get("claimId").getAsString());
        assertEquals("Jake", body.get("rsn").getAsString());
        assertFalse(body.has("accountHash"), "account hashes must not leave the client");
    }

    @Test
    void parsesAProgressResponseAsAnAnnounceableResolvedOutcome() throws Exception {
        server.enqueue(json("{\"status\":\"progress\",\"team\":\"Team One\",\"tileId\":\"rare-drop\"," +
            "\"tileName\":\"Any rare drop\",\"itemId\":4151,\"itemName\":\"Abyssal whip\"," +
            "\"progress\":1,\"required\":2,\"complete\":false,\"remaining\":4,\"total\":4}"));

        ClaimResponse response = client.submitClaim(claim()).get(5, TimeUnit.SECONDS);

        assertTrue(response.isProgress());
        assertTrue(response.isAnnounceable());
        assertTrue(response.isResolvedOutcome());
        assertFalse(response.isComplete());
        assertEquals(1, response.getProgress());
        assertEquals(2, response.getRequired());
    }

    @Test
    void parsesADuplicateResponseWithoutTreatingItAsClaimed() throws Exception {
        server.enqueue(json("{\"status\":\"duplicate\",\"team\":\"Team One\",\"itemId\":4151," +
            "\"itemName\":\"Abyssal whip\",\"claimedBy\":\"Teammate\",\"remaining\":4}"));

        ClaimResponse response = client.submitClaim(claim()).get(5, TimeUnit.SECONDS);

        assertFalse(response.isClaimed());
        assertEquals(BingoResponses.DUPLICATE, response.getStatus());
        assertEquals("Teammate", response.getClaimedBy());
    }

    /** A retried claim reuses the caller's claimId, so the backend can answer with a replay. */
    @Test
    void retriesServerErrorsAndSucceeds() throws Exception {
        server.enqueue(new MockResponse().setResponseCode(500));
        server.enqueue(json("{\"status\":\"claimed\",\"itemId\":4151,\"remaining\":1}"));

        ClaimResponse response = client.submitClaim(claim()).get(15, TimeUnit.SECONDS);

        assertNotNull(response);
        assertTrue(response.isClaimed());
        assertEquals(2, server.getRequestCount());

        String first = server.takeRequest().getBody().readUtf8();
        String second = server.takeRequest().getBody().readUtf8();
        assertEquals(
            new JsonParser().parse(first).getAsJsonObject().get("claimId").getAsString(),
            new JsonParser().parse(second).getAsJsonObject().get("claimId").getAsString(),
            "the retry must reuse the claimId or the backend cannot deduplicate it"
        );
    }

    @Test
    void retriesApplicationLevelRetryableErrorsWithTheSameClaimId() throws Exception {
        server.enqueue(json("{\"status\":\"error\",\"error\":\"lock_timeout\",\"retryable\":true}"));
        server.enqueue(json("{\"status\":\"claimed\",\"itemId\":4151,\"remaining\":1,\"total\":2}"));

        ClaimResponse response = client.submitClaim(claim()).get(15, TimeUnit.SECONDS);

        assertNotNull(response);
        assertTrue(response.isClaimed());
        assertEquals(2, server.getRequestCount());

        String first = server.takeRequest().getBody().readUtf8();
        String second = server.takeRequest().getBody().readUtf8();
        assertEquals(
            new JsonParser().parse(first).getAsJsonObject().get("claimId").getAsString(),
            new JsonParser().parse(second).getAsJsonObject().get("claimId").getAsString()
        );
    }

    @Test
    void doesNotRetryClientErrors() throws Exception {
        server.enqueue(new MockResponse().setResponseCode(404));

        ClaimResponse response = client.submitClaim(claim()).get(5, TimeUnit.SECONDS);

        assertNull(response);
        assertEquals(1, server.getRequestCount());
    }

    /** Apps Script serves an HTML error page when the deployment access level is wrong. */
    @Test
    void survivesANonJsonResponse() throws Exception {
        server.enqueue(new MockResponse()
            .setHeader("Content-Type", "text/html")
            .setBody("<!DOCTYPE html><html><body>Sorry, unable to open the file</body></html>"));

        assertNull(client.submitClaim(claim()).get(5, TimeUnit.SECONDS));
    }

    @Test
    void returnsEmptyBoardWhenNotConfigured() throws Exception {
        when(config.backendUrl()).thenReturn("");
        assertEquals(BingoBoard.EMPTY.getTiles(), client.fetchBoard("Jake").get(5, TimeUnit.SECONDS).getTiles());
        assertEquals(0, server.getRequestCount());
    }

    // ------------------------------------------------------------------

    private static ClaimRequest claim() {
        ClaimRequest claim = new ClaimRequest();
        claim.setRsn("Jake");
        claim.setItemId(4151);
        claim.setItemName("Abyssal whip");
        claim.setQuantity(1);
        claim.setSource("Abyssal demon");
        claim.setClaimId("claim-abc");
        return claim;
    }

    private static MockResponse json(String body) {
        return new MockResponse().setHeader("Content-Type", "application/json").setBody(body);
    }
}

package dinkbingo;

import dinkbingo.BingoResponses.ClaimRequest;
import dinkbingo.BingoResponses.ClaimResponse;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class BingoDetectorTest {

    private static final int WHIP = 4151;
    private static final int SCROLL = 21034;
    private static final int NOTED_WHIP = 4152;
    private static final int OFF_BOARD = 999;

    @Mock
    private Client client;

    @Mock
    private ItemManager itemManager;

    @Mock
    private BingoConfig config;

    @Mock
    private BingoClient bingoClient;

    @Mock
    private Player localPlayer;

    private BingoDetector detector;

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);

        when(client.getLocalPlayer()).thenReturn(localPlayer);
        when(localPlayer.getName()).thenReturn("Jake");
        when(config.includeCollectionLog()).thenReturn(true);
        when(bingoClient.isConfigured()).thenReturn(true);
        // Identity canonicalization by default; overridden in the noted-item test.
        when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));
        when(bingoClient.submitClaim(any())).thenReturn(new CompletableFuture<>());

        detector = new BingoDetector(client, itemManager, config, bingoClient);
        detector.setBoard(board(open(WHIP, "Abyssal whip"), open(SCROLL, "Dexterous prayer scroll")));
    }

    @Test
    void submitsClaimForItemOnBoard() {
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");

        ClaimRequest claim = captureClaim();
        assertEquals(WHIP, claim.getItemId());
        assertEquals("Abyssal whip", claim.getItemName());
        assertEquals("Jake", claim.getRsn());
        assertEquals("Abyssal demon", claim.getSource());
        assertEquals(1, claim.getQuantity());
        assertNotNull(claim.getClaimId(), "a claimId is required for backend idempotency");
    }

    @Test
    void ignoresItemNotOnBoard() {
        detector.onLoot(loot(OFF_BOARD, 1), "Goblin");
        verify(bingoClient, never()).submitClaim(any());
    }

    @Test
    void ignoresTileAlreadyClaimed() {
        detector.setBoard(board(claimed(WHIP, "Abyssal whip", "Teammate")));
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        verify(bingoClient, never()).submitClaim(any());
    }

    @Test
    void ignoresLootWhenPlayerHasNoTeam() {
        detector.setBoard(new BingoBoard(null, Collections.singletonList(open(WHIP, "Abyssal whip")), true));
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        verify(bingoClient, never()).submitClaim(any());
    }

    @Test
    void ignoresLootWhenEventClosed() {
        detector.setBoard(new BingoBoard("Team One", Collections.singletonList(open(WHIP, "Abyssal whip")), false));
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        verify(bingoClient, never()).submitClaim(any());
    }

    @Test
    void ignoresEverythingUntilBackendIsConfigured() {
        when(bingoClient.isConfigured()).thenReturn(false);
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        verify(bingoClient, never()).submitClaim(any());
    }

    /**
     * RuneLite fires both ServerNpcLoot and NpcLootReceived for some NPCs. Without the
     * in-flight guard that would be two claims and two audit rows for one kill.
     */
    @Test
    void submitsOnceWhenTheSameDropArrivesTwice() {
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");

        verify(bingoClient, times(1)).submitClaim(any());
    }

    @Test
    void alternativesShareInFlightState() {
        detector.setBoard(board(group("rare-drop", "Any rare drop",
            new BingoItem(WHIP, "Abyssal whip"),
            new BingoItem(SCROLL, "Dexterous prayer scroll"))));

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(SCROLL, 1), "Chambers of Xeric");

        verify(bingoClient, times(2)).submitClaim(any());
    }

    @Test
    void resolvedAlternativeSuppressesTheRestOfTheTile() {
        detector.setBoard(board(group("rare-drop", "Any rare drop",
            new BingoItem(WHIP, "Abyssal whip"),
            new BingoItem(SCROLL, "Dexterous prayer scroll"))));
        when(bingoClient.submitClaim(any()))
            .thenReturn(CompletableFuture.completedFuture(response(BingoResponses.CLAIMED)));

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(SCROLL, 1), "Chambers of Xeric");

        verify(bingoClient, times(1)).submitClaim(any());
    }

    @Test
    void differentThresholdOptionsCanAdvanceTogether() {
        detector.setBoard(board(thresholdGroup("rare-drop", "Two rare drops", 2,
            new BingoItem(WHIP, "Abyssal whip"),
            new BingoItem(SCROLL, "Dexterous prayer scroll"))));

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(SCROLL, 1), "Chambers of Xeric");

        verify(bingoClient, times(2)).submitClaim(any());
    }

    @Test
    void acceptedProgressSuppressesOnlyTheCreditedItem() {
        detector.setBoard(board(thresholdGroup("rare-drop", "Two rare drops", 2,
            new BingoItem(WHIP, "Abyssal whip"),
            new BingoItem(SCROLL, "Dexterous prayer scroll"))));
        ClaimResponse progress = response(BingoResponses.PROGRESS);
        progress.setTileId("rare-drop");
        progress.setProgress(1);
        progress.setRequired(2);
        progress.setComplete(false);
        when(bingoClient.submitClaim(any()))
            .thenReturn(CompletableFuture.completedFuture(progress), new CompletableFuture<>());

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(SCROLL, 1), "Chambers of Xeric");

        verify(bingoClient, times(2)).submitClaim(any());
    }

    /**
     * BingoPlugin deliberately forwards ServerNpcLoot, NpcLootReceived and LootReceived without
     * trying to work out which one "owns" a given kill, because upstream keeps moving bosses
     * between them. That is only safe if three events for one drop still yield one claim.
     */
    @Test
    void submitsOnceWhenTheSameDropArrivesFromEveryLootEvent() {
        detector.onLoot(loot(WHIP, 1), "Abyssal demon"); // ServerNpcLoot
        detector.onLoot(loot(WHIP, 1), "Abyssal demon"); // NpcLootReceived
        detector.onLoot(loot(WHIP, 1), "Abyssal demon"); // LootReceived (NPC)

        verify(bingoClient, times(1)).submitClaim(any());
    }

    @Test
    void allowsRetryAfterAnUnresolvedClaim() {
        CompletableFuture<ClaimResponse> failed = new CompletableFuture<>();
        when(bingoClient.submitClaim(any())).thenReturn(failed);

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        failed.complete(null); // backend unreachable

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        verify(bingoClient, times(2)).submitClaim(any());
    }

    @Test
    void doesNotResubmitAfterBackendResolvesTheTile() {
        when(bingoClient.submitClaim(any()))
            .thenReturn(CompletableFuture.completedFuture(response(BingoResponses.DUPLICATE)));

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");

        verify(bingoClient, times(1)).submitClaim(any());
    }

    @Test
    void allowsAnotherDropAfterARetryableBackendErrorExhaustsRetries() {
        ClaimResponse retryable = response(BingoResponses.ERROR);
        retryable.setRetryable(true);
        when(bingoClient.submitClaim(any()))
            .thenReturn(CompletableFuture.completedFuture(retryable), new CompletableFuture<>());

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");

        verify(bingoClient, times(2)).submitClaim(any());
    }

    @Test
    void authoritativeBoardRefreshReopensAnAdministrativelyUnclaimedTile() {
        when(bingoClient.submitClaim(any()))
            .thenReturn(CompletableFuture.completedFuture(response(BingoResponses.CLAIMED)),
                new CompletableFuture<>());

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.setBoard(board(open(WHIP, "Abyssal whip")));
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");

        verify(bingoClient, times(2)).submitClaim(any());
    }

    @Test
    void canonicalizesNotedItemsBeforeMatching() {
        when(itemManager.canonicalize(NOTED_WHIP)).thenReturn(WHIP);

        detector.onLoot(loot(NOTED_WHIP, 1), "Abyssal demon");

        assertEquals(WHIP, captureClaim().getItemId());
    }

    @Test
    void claimsFromCollectionLogByName() {
        detector.onGameMessage("New item added to your collection log: Dexterous prayer scroll");

        ClaimRequest claim = captureClaim();
        assertEquals(SCROLL, claim.getItemId());
        assertEquals("Collection log", claim.getSource());
    }

    @Test
    void claimsAGroupedAlternativeFromCollectionLogByName() {
        detector.setBoard(board(group("rare-drop", "Any rare drop",
            new BingoItem(WHIP, "Abyssal whip"),
            new BingoItem(SCROLL, "Dexterous prayer scroll"))));

        detector.onGameMessage("New item added to your collection log: Dexterous prayer scroll");

        ClaimRequest claim = captureClaim();
        assertEquals(SCROLL, claim.getItemId());
        assertEquals("Dexterous prayer scroll", claim.getItemName());
    }

    @Test
    void ignoresCollectionLogWhenDisabled() {
        when(config.includeCollectionLog()).thenReturn(false);
        detector.onGameMessage("New item added to your collection log: Dexterous prayer scroll");
        verify(bingoClient, never()).submitClaim(any());
    }

    @Test
    void ignoresUnrelatedGameMessages() {
        detector.onGameMessage("You feel something weird sneaking into your backpack.");
        verify(bingoClient, never()).submitClaim(any());
    }

    @Test
    void notifiesListenerWithTheBackendResponse() {
        ClaimResponse expected = response(BingoResponses.CLAIMED);
        when(bingoClient.submitClaim(any())).thenReturn(CompletableFuture.completedFuture(expected));

        List<ClaimResponse> seen = new ArrayList<>();
        detector.setClaimListener((res, source) -> seen.add(res));

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");

        assertEquals(1, seen.size());
        assertTrue(seen.get(0).isClaimed());
    }

    /**
     * The source must travel with the claim rather than be read from shared state: a second
     * drop can land while the first claim is still waiting on the backend, and the
     * announcement would otherwise name the wrong monster.
     */
    @Test
    void reportsTheSourceOfEachClaimEvenWhenAnotherDropInterleaves() {
        CompletableFuture<ClaimResponse> whipCall = new CompletableFuture<>();
        CompletableFuture<ClaimResponse> scrollCall = new CompletableFuture<>();
        when(bingoClient.submitClaim(any())).thenReturn(whipCall, scrollCall);

        List<String> sources = new ArrayList<>();
        detector.setClaimListener((res, source) -> sources.add(source));

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.onLoot(loot(SCROLL, 1), "Chambers of Xeric");

        // The scroll's backend call resolves first, then the whip's.
        scrollCall.complete(response(BingoResponses.CLAIMED));
        whipCall.complete(response(BingoResponses.CLAIMED));

        assertEquals(Arrays.asList("Chambers of Xeric", "Abyssal demon"), sources);
    }

    @Test
    void resetClearsBoardAndDedupeState() {
        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.reset();

        assertEquals(BingoBoard.EMPTY, detector.getBoard());
        assertTrue(detector.getBoard().getRemaining().isEmpty());
    }

    @Test
    void completionFromBeforeResetDoesNotNotifyTheNewSessionListener() {
        CompletableFuture<ClaimResponse> oldClaim = new CompletableFuture<>();
        when(bingoClient.submitClaim(any())).thenReturn(oldClaim);
        List<ClaimResponse> seen = new ArrayList<>();
        detector.setClaimListener((response, source) -> seen.add(response));

        detector.onLoot(loot(WHIP, 1), "Abyssal demon");
        detector.reset();
        detector.setBoard(board(open(WHIP, "Abyssal whip")));
        oldClaim.complete(response(BingoResponses.CLAIMED));

        assertTrue(seen.isEmpty());
    }

    // ------------------------------------------------------------------

    private ClaimRequest captureClaim() {
        ArgumentCaptor<ClaimRequest> captor = ArgumentCaptor.forClass(ClaimRequest.class);
        verify(bingoClient).submitClaim(captor.capture());
        return captor.getValue();
    }

    private static List<ItemStack> loot(int id, int quantity) {
        return Collections.singletonList(new ItemStack(id, quantity));
    }

    private static BingoBoard board(BingoTile... tiles) {
        return new BingoBoard("Team One", Arrays.asList(tiles), true);
    }

    private static BingoTile open(int id, String name) {
        return group(String.valueOf(id), name, new BingoItem(id, name));
    }

    private static BingoTile claimed(int id, String name, String by) {
        BingoItem item = new BingoItem(id, name);
        BingoContribution contribution =
            new BingoContribution(id, name, by, "2026-07-30T00:00:00Z");
        return new BingoTile(String.valueOf(id), name, 1, 1, 1,
            Collections.singletonList(item), Collections.singletonList(contribution),
            true, by, "2026-07-30T00:00:00Z", item);
    }

    private static BingoTile group(String id, String name, BingoItem... options) {
        return thresholdGroup(id, name, 1, options);
    }

    private static BingoTile thresholdGroup(String id, String name, int required, BingoItem... options) {
        return new BingoTile(id, name, 1, required, 0, Arrays.asList(options),
            Collections.emptyList(), false, null, null, null);
    }

    private static ClaimResponse response(String status) {
        ClaimResponse response = new ClaimResponse();
        response.setStatus(status);
        response.setTeam("Team One");
        response.setTileId(String.valueOf(WHIP));
        response.setTileName("Abyssal whip");
        response.setItemId(WHIP);
        response.setItemName("Abyssal whip");
        response.setProgress(BingoResponses.CLAIMED.equals(status) ? 1 : 0);
        response.setRequired(1);
        response.setComplete(BingoResponses.CLAIMED.equals(status)
            || BingoResponses.DUPLICATE.equals(status));
        response.setRemaining(1);
        response.setTotal(2);
        return response;
    }
}

package dinkbingo;

import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.jupiter.api.Test;

import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Component;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class BingoPanelTest {

    @Test
    void longTileListScrollsWhileHeaderRemainsFixed() throws Exception {
        ItemManager itemManager = mock(ItemManager.class);
        when(itemManager.getImage(anyInt())).thenReturn(mock(AsyncBufferedImage.class));
        BingoPanel panel = new BingoPanel(itemManager);

        BorderLayout layout = (BorderLayout) panel.getLayout();
        Component center = layout.getLayoutComponent(BorderLayout.CENTER);
        Component header = layout.getLayoutComponent(BorderLayout.NORTH);

        assertTrue(center instanceof JScrollPane);
        JScrollPane scrollPane = (JScrollPane) center;
        assertEquals(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            scrollPane.getVerticalScrollBarPolicy());
        assertEquals(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER,
            scrollPane.getHorizontalScrollBarPolicy());

        List<BingoTile> tiles = new ArrayList<>();
        for (int i = 0; i < 50; i++) {
            int itemId = i + 1;
            String name = "Tile " + itemId;
            BingoItem option = new BingoItem(itemId, name);
            tiles.add(new BingoTile(
                String.valueOf(itemId),
                name,
                1,
                1,
                0,
                Collections.singletonList(option),
                Collections.emptyList(),
                false,
                null,
                null,
                null
            ));
        }
        panel.render(new BingoBoard("Team One", tiles, true), true,
            BoardView.NAMED_TILES, false);
        SwingUtilities.invokeAndWait(() -> {
            // Flush the render queued by BingoPanel.render.
        });

        JPanel itemList = (JPanel) scrollPane.getViewport().getView();
        assertEquals(50, itemList.getComponentCount());
        assertTrue(itemList.getPreferredSize().height > 400);
        assertNotSame(header, itemList);
    }

    @Test
    void completedTilesCanBeHiddenForTheCurrentTeam() throws Exception {
        ItemManager itemManager = mock(ItemManager.class);
        when(itemManager.getImage(anyInt())).thenReturn(mock(AsyncBufferedImage.class));
        BingoPanel panel = new BingoPanel(itemManager);

        BingoTile open = tile(1, "Open tile", false);
        BingoTile completed = tile(2, "Completed tile", true);
        BingoBoard board = new BingoBoard("Team One",
            java.util.Arrays.asList(open, completed), true);

        panel.render(board, true, BoardView.NAMED_TILES, true);
        SwingUtilities.invokeAndWait(() -> {
            // Flush the render queued by BingoPanel.render.
        });

        BorderLayout layout = (BorderLayout) panel.getLayout();
        JScrollPane scrollPane = (JScrollPane) layout.getLayoutComponent(BorderLayout.CENTER);
        JPanel itemList = (JPanel) scrollPane.getViewport().getView();
        assertEquals(1, itemList.getComponentCount());
    }

    @Test
    void possibleItemsShowsOnlyEligibleOptionsForUnfinishedTiles() throws Exception {
        ItemManager itemManager = mock(ItemManager.class);
        when(itemManager.getImage(anyInt())).thenReturn(mock(AsyncBufferedImage.class));
        BingoPanel panel = new BingoPanel(itemManager);

        BingoTile unfinished = new BingoTile(
            "raids",
            "Any two raids uniques",
            2,
            2,
            1,
            java.util.Arrays.asList(
                new BingoItem(1, "Dexterous prayer scroll"),
                new BingoItem(2, "Arcane prayer scroll"),
                new BingoItem(3, "Twisted buckler")
            ),
            Collections.singletonList(new BingoContribution(
                1, "Dexterous prayer scroll", "Jake", "2026-07-31T12:00:00Z")),
            false,
            null,
            null,
            null
        );
        BingoTile completed = tile(4, "Completed item", true);

        panel.render(new BingoBoard("Team One",
                java.util.Arrays.asList(unfinished, completed), true),
            true, BoardView.POSSIBLE_ITEMS, false);
        SwingUtilities.invokeAndWait(() -> {
            // Flush the render queued by BingoPanel.render.
        });

        BorderLayout layout = (BorderLayout) panel.getLayout();
        JScrollPane scrollPane = (JScrollPane) layout.getLayoutComponent(BorderLayout.CENTER);
        JPanel itemList = (JPanel) scrollPane.getViewport().getView();
        assertEquals(2, itemList.getComponentCount());
        assertEquals("Arcane prayer scroll", rowName(itemList.getComponent(0)));
        assertEquals("Twisted buckler", rowName(itemList.getComponent(1)));
        assertEquals("1 of 2 tiles left", statusText(panel));
    }

    private static String rowName(Component component) {
        JPanel row = (JPanel) component;
        return ((javax.swing.JLabel) ((BorderLayout) row.getLayout())
            .getLayoutComponent(BorderLayout.CENTER)).getText();
    }

    private static String statusText(BingoPanel panel) {
        BorderLayout panelLayout = (BorderLayout) panel.getLayout();
        JPanel header = (JPanel) panelLayout.getLayoutComponent(BorderLayout.NORTH);
        JPanel titles = (JPanel) ((BorderLayout) header.getLayout())
            .getLayoutComponent(BorderLayout.CENTER);
        return ((javax.swing.JLabel) titles.getComponent(1)).getText();
    }

    private static BingoTile tile(int id, String name, boolean claimed) {
        BingoItem item = new BingoItem(id, name);
        return new BingoTile(
            String.valueOf(id),
            name,
            1,
            1,
            claimed ? 1 : 0,
            Collections.singletonList(item),
            Collections.emptyList(),
            claimed,
            claimed ? "Jake" : null,
            null,
            claimed ? item : null
        );
    }
}

package dinkbingo;

